errs=[]
def ok(c,m):
  print(('  ok - ' if c else '  FAIL - ')+m)
  if not c: errs.append(m)
async def staff(ctx, page, email):
  q=await ctx.new_page(); q.on('pageerror',lambda e:errs.append(page+': '+str(e)))
  await q.goto(P+page); await q.evaluate("['admin','merchant','rider'].forEach(k=>localStorage.removeItem('tr5_staff_'+k))"); await q.reload(); await q.wait_for_selector('#lgE'); await q.fill('#lgE',email); await q.click('#lgBtn'); await q.wait_for_selector('#lgV'); await q.click('#lgV'); await q.wait_for_timeout(1200)
  return q
async def tab(q, name):
  await q.locator('.ptabs button', has_text=name).first.click(); await q.wait_for_timeout(500)
